import requests, re, numpy as np, pandas as pd, matplotlib.pyplot as plt, os, json
AA3={'ALA':'A','ARG':'R','ASN':'N','ASP':'D','CYS':'C','GLN':'Q','GLU':'E','GLY':'G','HIS':'H','ILE':'I',
'LEU':'L','LYS':'K','MET':'M','PHE':'F','PRO':'P','SER':'S','THR':'T','TRP':'W','TYR':'Y','VAL':'V'}
def ppdb(t):
    at=[]
    for l in t.split('\n'):
        if l.startswith(('ATOM','HETATM')) and l[16] in (' ','A'):
            try: at.append(dict(rec=l[:6].strip(),name=l[12:16].strip(),resn=l[17:20].strip(),ch=l[21],
                resi=int(l[22:26]),xyz=np.array([float(l[30:38]),float(l[38:46]),float(l[46:54])]),
                b=float(l[60:66]) if l[60:66].strip() else 0.0))
            except ValueError: pass
    return at
def kabsch(P,Q):
    Pc=P.mean(0);Qc=Q.mean(0);H=(P-Pc).T@(Q-Qc);U,S,Vt=np.linalg.svd(H)
    d=np.sign(np.linalg.det(Vt.T@U.T));R=Vt.T@np.diag([1,1,d])@U.T
    return R,Qc-R@Pc

# ---- AOPEP AlphaFold model ----
api=requests.get('https://alphafold.ebi.ac.uk/api/prediction/Q8N6M6',timeout=120).json()
af=ppdb(requests.get(api[0]['pdbUrl'],timeout=180).text)
af_ca={a['resi']:a['xyz'] for a in af if a['name']=='CA'}
af_res={a['resi']:AA3.get(a['resn'],'X') for a in af if a['name']=='CA'}
af_plddt={a['resi']:a['b'] for a in af if a['name']=='CA'}
af_all={}
for a in af: af_all.setdefault(a['resi'],[]).append(a)

TEMPL={'1HS6':dict(chain='A',lig='BES',anchors={479:295,480:296,483:299,502:318,586:383,452:269,453:270,456:273},name='LTA4H + bestatin'),
       '3MDJ':dict(chain='A',lig='BES',anchors={479:353,480:354,483:357,502:376,586:438,453:319,454:320},name='ERAP1 + bestatin')}
out={}
for pid,cfg in TEMPL.items():
    at=ppdb(requests.get(f'https://files.rcsb.org/download/{pid}.pdb',timeout=180).text)
    at=[a for a in at if a['ch']==cfg['chain']]
    tca={a['resi']:a['xyz'] for a in at if a['name']=='CA' and a['rec']=='ATOM'}
    tres={a['resi']:AA3.get(a['resn'],'X') for a in at if a['name']=='CA' and a['rec']=='ATOM'}
    tall={}
    for a in at:
        if a['rec']=='ATOM': tall.setdefault(a['resi'],[]).append(a)
    lig=[a for a in at if a['rec']=='HETATM' and a['resn']==cfg['lig']]
    # verify anchors
    ok={f"AOPEP {af_res[k]}{k} -> {pid} {tres.get(v,'?')}{v}":(af_res[k]==tres.get(v) or (k,v) in [(452,269),(453,270),(456,273),(453,319),(454,320)])
        for k,v in cfg['anchors'].items()}
    print(f"--- {pid} ({cfg['name']}) anchor check, {len(lig)} ligand atoms ---")
    for k,v in ok.items(): print(('  OK  ' if v else '  MISMATCH ')+k)
    pr=[(k,v) for k,v in cfg['anchors'].items() if k in af_ca and v in tca]
    R,t=kabsch(np.array([af_ca[k] for k,v in pr]),np.array([tca[v] for k,v in pr]))
    afk=sorted(af_ca); tk=sorted(tca)
    for it in range(12):
        P=np.array([R@af_ca[k]+t for k in afk]); Q=np.array([tca[k] for k in tk])
        D=np.linalg.norm(P[:,None]-Q[None],axis=2); i2j=D.argmin(1); j2i=D.argmin(0)
        mut=[(a,b) for a,b in enumerate(i2j) if j2i[b]==a and D[a,b]<5.0]
        R,t=kabsch(np.array([af_ca[afk[a]] for a,b in mut]),np.array([tca[tk[b]] for a,b in mut]))
    rms=float(np.sqrt(np.mean([np.sum((R@af_ca[afk[a]]+t-tca[tk[b]])**2) for a,b in mut])))
    corr={afk[a]:tk[b] for a,b in mut}
    print(f"  superposition: {len(mut)} CA pairs, RMSD {rms:.2f} A")
    # S1 pocket: template residues lining the bestatin phenyl (P1 side chain)
    ligxyz=np.array([a['xyz'] for a in lig]); lignm=[a['name'] for a in lig]
    # P1 phenyl ring atoms of bestatin
    ring=[i for i,n in enumerate(lignm) if n in ('C1','C2','C3','C4','C5','C6','CD1','CD2','CE1','CE2','CZ','CG')]
    ringxyz=ligxyz[ring] if ring else ligxyz
    pocket=[]
    inv={v:k for k,v in corr.items()}
    for ti,atoms in tall.items():
        dmin=min(float(np.min(np.linalg.norm(ringxyz-a['xyz'],axis=1))) for a in atoms)
        if dmin<5.5 and ti in inv:
            ai=inv[ti]
            pocket.append(dict(template=pid, templ_res=f"{tres[ti]}{ti}", dist_to_P1_A=round(dmin,2),
                               aopep_res=f"{af_res[ai]}{ai}", aopep_pos=ai, pLDDT=af_plddt[ai],
                               identical=(tres[ti]==af_res[ai])))
    out[pid]=pd.DataFrame(pocket).sort_values('dist_to_P1_A')
    print(f"  S1 pocket (template residues within 5.5 A of bestatin P1 ring atoms, {len(pocket)} residues):")
    print(out[pid].to_string(index=False)); print()

S1=pd.concat(out.values())
os.makedirs('provenance',exist_ok=True)
S1.to_csv('provenance/S1_pocket_comparison.csv',index=False)
print("S1 pocket identity to template:", f"{int(S1['identical'].sum())}/{len(S1)}")
print("AOPEP S1 residues shared by both template frames:",
      sorted(set(out['1HS6']['aopep_pos']) & set(out['3MDJ']['aopep_pos'])))

fig,ax=plt.subplots(figsize=(9,4.2))
d=S1.sort_values('dist_to_P1_A')
ax.barh(range(len(d)),d['dist_to_P1_A'],color=['#27ae60' if i else '#c0392b' for i in d['identical']])
ax.set_yticks(range(len(d)));ax.set_yticklabels([f"{r.template} {r.templ_res} -> AOPEP {r.aopep_res}" for r in d.itertuples()],fontsize=7,fontfamily='monospace')
ax.invert_yaxis();ax.set_xlabel('template residue distance to bestatin P1 ring (A)')
ax.set_title('S1 pocket positions mapped from bestatin-bound LTA4H and ERAP1 onto AOPEP\ngreen = identical residue, red = substituted',fontsize=10)
plt.tight_layout();plt.show()
